import torch
import candidate, reference

cfgs = [(4096, 1024), (4096, 4096), (8192, 1000), (8192, 2048), (2048, 512)]
xs = {c: torch.randn(c[0], c[1], device="cuda") for c in cfgs}

# warmup all
for c in cfgs:
    for _ in range(20):
        candidate.run(xs[c])
torch.cuda.synchronize()

def bench(fn, x, iters=200):
    for _ in range(10):
        fn(x)
    torch.cuda.synchronize()
    s = torch.cuda.Event(True); e = torch.cuda.Event(True)
    s.record()
    for _ in range(iters):
        fn(x)
    e.record(); torch.cuda.synchronize()
    return s.elapsed_time(e) / iters * 1e3  # us

for c in cfgs:
    x = xs[c]
    us = bench(candidate.run, x)
    gb = x.numel() * 4 * 2 / 1e9
    ref = reference.run(x)
    ok = torch.allclose(candidate.run(x), ref, rtol=1e-4, atol=1e-4)
    print(f"M={c[0]:5d} N={c[1]:5d}  {us:8.1f} us  {gb/(us/1e6):7.1f} GB/s  ok={ok}")
